// src/lib/style/index.js
function toStyleString(style) {
  if (!style) return null;
  if (typeof style === "string") return style;
  return Object.entries(style).map(([k, v]) => {
    if (k.startsWith("--")) return `${k}:${v}`;
    else return `${toKebab(k)}:${v}`;
  }).join("; ").concat(";");
}

